create function portfolio_private.validate_entity() returns trigger language plpgsql security definer set search_path='' as $$
declare v_schema jsonb; v_block jsonb; v_url text;
begin
  select json_schema into strict v_schema from portfolio_private.entity_schemas where kind=new.kind;
  if not extensions.jsonb_matches_schema(v_schema::json,new.data) then raise exception 'Entity does not match content schema version 1' using errcode='22023'; end if;
  if new.kind='settings' and new.data->>'siteUrl'<>'https://spatovaliyski.com' then raise exception 'Unexpected public origin'; end if;
  -- Custom Zod refinements supplement the shared structural JSON Schema.
  for v_block in select value from jsonb_array_elements(coalesce(new.data->'blocks','[]')) loop
    if v_block->>'type'='prose' and (v_block->>'markdown' ~* '<\/?[a-z][^>]*>' or v_block->>'markdown' ~* '\]\(\s*(javascript|data|vbscript):') then raise exception 'Raw HTML and executable embeds are not supported' using errcode='22023'; end if;
  end loop;
  for v_url in select distinct value#>>'{}' from jsonb_path_query(new.data,'$.**.url') value where jsonb_typeof(value)='string'
    union select distinct value#>>'{}' from jsonb_path_query(new.data,'$.**.sourceUrl') value where jsonb_typeof(value)='string' loop
